import {mixSequencePoseEntries} from './sequence-pose-blending.js';
import {mixIndexedPoseEntries} from './sequence-indexed-transforms.js';
export const skeletalSequenceKey=bone=>'skeletalPose:'+bone;
const batches=new WeakMap();
function skeletalBatch(hooks,channels){if(!hooks.batchSkeletal)return;let batch=batches.get(hooks);if(!batch){batch=changes=>hooks.batchSkeletal(changes.map(({target,key,value})=>({id:target.id,...value,...value.baseline?{retain:channels.hasPrefix(target,'skeletalPose:'),watch:channels.has(target,key)}:{}})));batches.set(hooks,batch);}return batch;}
export function prepareSequencePoseChannels(channels,state,id,vm,hooks,animationPlans=new Map()){
 const plans=new Map(),newBones=new Map();
 for(const track of state.sampleTracks){if(track.type!=='skeletalPose'||(track.poseWeight??1)<=0)continue;const target=state.spawns.resolve(track.target||id),object=vm.object(target);if(!object||!object.sequencePlayback&&state.targets.get(target)!==object)continue;const value=state.sampler.sample(track,state.time,{reference:true});if(value===undefined)continue;const bones=value.map(row=>row.bone);plans.set(track,{object,track,time:state.time,bones,value});for(const bone of bones)if(!channels.has(object,skeletalSequenceKey(bone))){let names=newBones.get(object);if(!names){names=new Set();newBones.set(object,names);}names.add(bone);}}
 for(const [track,plan]of animationPlans){plans.set(track,plan);for(const bone of plan.bones)if(!channels.has(plan.object,skeletalSequenceKey(bone))){let names=newBones.get(plan.object);if(!names){names=new Set();newBones.set(plan.object,names);}names.add(bone);}}
 const baselines=new Map();for(const [object,names]of newBones)baselines.set(object,hooks.captureSkeletal(object.id,[...names]));return {plans,baselines};
}
export async function writeSequencePoseChannels(channels,state,changes,baselines,vm,hooks,current){
 const active=new Map(),updates=[],batchNow=!!hooks.batchSkeletal&&(state.seek||state.blendMode==='normalized'||changes.some(plan=>plan.track.importedPose));for(const {object,track,time,bones,sparseBones,completionMode=track.completionMode}of changes){let names=active.get(object);if(!names){names=new Set();active.set(object,names);}for(const bone of bones){names.add(bone);const key=skeletalSequenceKey(bone),value={track,time,bone},options=()=>({mix:hooks.batchSkeletal?mixSequencePoseEntries:undefined,read:()=>({baseline:baselines.get(object)??hooks.captureSkeletal(object.id,[bone]),bone}),apply:(sample,restoring)=>(sample.layers||sample.track?.importedPose||sample.baseline)&&hooks.batchSkeletal?hooks.batchSkeletal([{id:object.id,...sample,...sample.baseline?{retain:channels.hasPrefix(object,'skeletalPose:'),watch:channels.has(object,key)}:{}}]):sample.baseline?hooks.restoreSkeletal?.(object.id,sample.baseline,sample.bone):hooks.sampleSkeletal(object.id,sample.track,sample.time,restoring,sample.bone),batch:skeletalBatch(hooks,channels),empty:()=>hooks.batchSkeletal?hooks.batchSkeletal([{id:object.id,clear:true,bone,retain:channels.hasPrefix(object,'skeletalPose:'),watch:channels.has(object,key)}]):hooks.clearSkeletal?.(object.id,bone),valid:()=>vm.object(object.id)===object});if(batchNow)updates.push({target:object,key,value,options,resolve:sparseBones?.has(bone)?mixIndexedPoseEntries:undefined,completionMode});else await channels.write(state,object,key,value,options,completionMode);if(!current())return false;}}
 if(updates.length){const targets=new Map();for(const row of updates){let fields=targets.get(row.target);if(!fields){fields=new Map();targets.set(row.target,fields);}fields.set(row.key,row);}await channels.writeBatch(state,[...targets.values()].flatMap(fields=>[...fields.values()]));if(!current())return false;}
 for(const [object,names]of state.poseFields||[])for(const bone of names)if(!active.get(object)?.has(bone)){await channels.releaseField(state,object,skeletalSequenceKey(bone),{defaultRestore:state.data.restoreState,forceRestore:state.data.forceRestore===true});if(!current())return false;}state.poseFields=active;return true;
}
